// ===== THEME TOGGLE =====
(function() {
  const toggle = document.querySelector('[data-theme-toggle]');
  const root = document.documentElement;
  let theme = matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  root.setAttribute('data-theme', theme);
  
  if (toggle) {
    updateToggleIcon(toggle, theme);
    toggle.addEventListener('click', () => {
      theme = theme === 'dark' ? 'light' : 'dark';
      root.setAttribute('data-theme', theme);
      updateToggleIcon(toggle, theme);
    });
  }
  
  function updateToggleIcon(btn, t) {
    btn.setAttribute('aria-label', 'Switch to ' + (t === 'dark' ? 'light' : 'dark') + ' mode');
    btn.innerHTML = t === 'dark' 
      ? '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg>'
      : '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>';
  }
})();

// ===== HEADER SCROLL =====
(function() {
  const header = document.querySelector('.header');
  if (!header) return;
  let lastY = 0;
  window.addEventListener('scroll', () => {
    const y = window.scrollY;
    header.classList.toggle('header--scrolled', y > 20);
    lastY = y;
  }, { passive: true });
})();

// ===== MOBILE MENU =====
(function() {
  const btn = document.querySelector('.mobile-menu-btn');
  const nav = document.querySelector('.header__nav');
  if (!btn || !nav) return;
  btn.addEventListener('click', () => {
    nav.classList.toggle('open');
  });
})();

// ===== SCROLL ANIMATIONS =====
(function() {
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(e => {
      if (e.isIntersecting) {
        e.target.classList.add('visible');
        observer.unobserve(e.target);
      }
    });
  }, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });

  function observe() {
    document.querySelectorAll('.fade-up, .stagger').forEach(el => observer.observe(el));
  }
  
  // Re-observe on route change
  window.observeAnimations = observe;
  observe();
})();

// ===== ROUTER =====
function getRoute() {
  const hash = window.location.hash.replace('#', '');
  if (hash.startsWith('class-')) {
    const num = parseInt(hash.replace('class-', ''));
    if (num >= 1 && num <= 8) return { page: 'class', classNum: num };
  }
  return { page: 'home' };
}

function navigate(hash) {
  window.location.hash = hash;
}

// ===== FORMATTERS =====
function formatCurrency(num) {
  if (num >= 1000000) return '$' + (num / 1000000).toFixed(1) + 'M';
  if (num >= 1000) return '$' + (num / 1000).toFixed(0) + 'K';
  return '$' + num.toLocaleString();
}

function textToHtml(text) {
  // Convert markdown-like bold and basic formatting
  return text
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\n\n/g, '</p><p>')
    .replace(/\n/g, '<br>');
}

// ===== CHART RENDERING =====
let chartInstances = [];

function destroyCharts() {
  chartInstances.forEach(c => c.destroy());
  chartInstances = [];
}

function renderChart(chartData, canvasId) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  
  const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
  const textColor = isDark ? '#a0aec0' : '#4a5568';
  const gridColor = isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)';
  
  // Override chart colors for brand consistency
  const brandColors = ['#00d4aa', '#667eea', '#f0b429', '#e53e3e', '#38b2ac', '#a78bfa'];
  if (chartData.data && chartData.data.datasets) {
    chartData.data.datasets.forEach((ds, i) => {
      if (chartData.type === 'doughnut' || chartData.type === 'pie') {
        // For pie/doughnut, use array of colors
        if (!ds.backgroundColor || typeof ds.backgroundColor === 'string') {
          ds.backgroundColor = brandColors;
          ds.borderColor = isDark ? '#1a1a2e' : '#ffffff';
          ds.borderWidth = 2;
        }
      } else {
        // For line/bar, keep existing colors but ensure visibility
        if (!ds.borderColor) ds.borderColor = brandColors[i % brandColors.length];
        if (!ds.backgroundColor && chartData.type === 'bar') {
          ds.backgroundColor = brandColors[i % brandColors.length] + '99';
        }
      }
    });
  }
  
  const config = {
    type: chartData.type,
    data: chartData.data,
    options: {
      responsive: true,
      maintainAspectRatio: true,
      animation: { duration: 800, easing: 'easeOutQuart' },
      plugins: {
        legend: {
          display: true,
          position: 'bottom',
          labels: {
            color: textColor,
            font: { family: "'Satoshi', sans-serif", size: 12 },
            padding: 16,
            usePointStyle: true,
            pointStyle: 'circle'
          }
        },
        tooltip: {
          backgroundColor: isDark ? '#1a1a2e' : '#ffffff',
          titleColor: isDark ? '#e2e8f0' : '#1a1a2e',
          bodyColor: isDark ? '#a0aec0' : '#4a5568',
          borderColor: isDark ? '#3d3d5c' : '#d1d9e6',
          borderWidth: 1,
          cornerRadius: 8,
          padding: 12,
          titleFont: { family: "'Satoshi', sans-serif", weight: '700' },
          bodyFont: { family: "'Satoshi', sans-serif" },
          callbacks: {
            label: function(ctx) {
              let label = ctx.dataset.label || '';
              if (label) label += ': ';
              if (ctx.parsed.y !== null && ctx.parsed.y !== undefined) {
                label += '$' + ctx.parsed.y.toLocaleString();
              } else if (ctx.parsed !== null) {
                label += ctx.parsed + '%';
              }
              return label;
            }
          }
        }
      },
      scales: chartData.type !== 'doughnut' && chartData.type !== 'pie' ? {
        x: {
          grid: { color: gridColor },
          ticks: { color: textColor, font: { family: "'Satoshi', sans-serif", size: 11 } }
        },
        y: {
          grid: { color: gridColor },
          ticks: {
            color: textColor,
            font: { family: "'Satoshi', sans-serif", size: 11 },
            callback: function(val) {
              if (Math.abs(val) >= 1000000) return '$' + (val/1000000).toFixed(1) + 'M';
              if (Math.abs(val) >= 1000) return '$' + (val/1000).toFixed(0) + 'K';
              if (Math.abs(val) < 100 && val !== 0 && String(val).indexOf('.') === -1) return val + '%';
              return '$' + val.toLocaleString();
            }
          }
        }
      } : undefined
    }
  };
  
  const chart = new Chart(canvas, config);
  chartInstances.push(chart);
}

